mapper.select:
SELECT a.id, a.title, a.summary, a.cover_image, a.category_id,
       a.views, a.status, a.created_at, a.updated_at
FROM articles a


        AND (LOWER(a.title) LIKE LOWER(CONCAT('%', #{keyword}, '%')) ESCAPE '/'
          OR LOWER(a.content) LIKE LOWER(CONCAT('%', #{keyword}, '%')) ESCAPE '/')


        AND a.status = #{status}


        AND a.category_id = #{categoryId}


        AND EXISTS (
            SELECT 1
            FROM article_tags filter_at
            WHERE filter_at.article_id = a.id
              AND filter_at.tag_id = #{tagId}
        )


ORDER BY a.created_at DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM articles a


        AND (LOWER(a.title) LIKE LOWER(CONCAT('%', #{keyword}, '%')) ESCAPE '/'
          OR LOWER(a.content) LIKE LOWER(CONCAT('%', #{keyword}, '%')) ESCAPE '/')


        AND a.status = #{status}


        AND a.category_id = #{categoryId}


        AND EXISTS (
            SELECT 1
            FROM article_tags filter_at
            WHERE filter_at.article_id = a.id
              AND filter_at.tag_id = #{tagId}
        )
